/// Any node deriving from slang's abstract `NetStrengthSyntax`.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub enum NetStrengthSyntax<'t> {
    /// A [`ChargeStrengthSyntax`].
    ChargeStrength(ChargeStrengthSyntax<'t>),
    /// A [`DriveStrengthSyntax`].
    DriveStrength(DriveStrengthSyntax<'t>),
    /// A [`PullStrengthSyntax`].
    PullStrength(PullStrengthSyntax<'t>),
}

impl<'t> AstNode<'t> for NetStrengthSyntax<'t> {
    fn can_cast(kind: SyntaxKind) -> bool {
        matches!(
            kind.syntax_struct(),
            Some(SyntaxStruct::ChargeStrengthSyntax)
                | Some(SyntaxStruct::DriveStrengthSyntax)
                | Some(SyntaxStruct::PullStrengthSyntax)
        )
    }

    fn cast(node: Node<'t>) -> Option<Self> {
        if let Some(n) = <ChargeStrengthSyntax<'t>>::cast(node) {
            return Some(Self::ChargeStrength(n));
        }
        if let Some(n) = <DriveStrengthSyntax<'t>>::cast(node) {
            return Some(Self::DriveStrength(n));
        }
        if let Some(n) = <PullStrengthSyntax<'t>>::cast(node) {
            return Some(Self::PullStrength(n));
        }
        None
    }

    fn syntax(&self) -> Node<'t> {
        match self {
            Self::ChargeStrength(n) => n.syntax(),
            Self::DriveStrength(n) => n.syntax(),
            Self::PullStrength(n) => n.syntax(),
        }
    }
}

impl core::fmt::Debug for NetStrengthSyntax<'_> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        core::fmt::Debug::fmt(&self.syntax(), f)
    }
}

impl<'t> From<ChargeStrengthSyntax<'t>> for NetStrengthSyntax<'t> {
    fn from(n: ChargeStrengthSyntax<'t>) -> Self {
        Self::ChargeStrength(n)
    }
}

impl<'t> From<DriveStrengthSyntax<'t>> for NetStrengthSyntax<'t> {
    fn from(n: DriveStrengthSyntax<'t>) -> Self {
        Self::DriveStrength(n)
    }
}

impl<'t> From<PullStrengthSyntax<'t>> for NetStrengthSyntax<'t> {
    fn from(n: PullStrengthSyntax<'t>) -> Self {
        Self::PullStrength(n)
    }
}

